// A deterministic local random source. Recreate it in run() on replay.
function makeRandom(seed: number) {
  let state = seed >>> 0;
  return () => {
    state = (1664525 * state + 1013904223) >>> 0;
    return state / 4294967296;
  };
}
const random = makeRandom(42);
const x = -2 + 4 * random();
